const b = $input.first().json.body || $input.first().json;
const paqueteEmoji = { 'Starter': '🥉', 'Pro': '🥈', 'Premium': '🥇' };
const emoji = paqueteEmoji[b.paquete] || '📋';

return [{ json: {
  content: [
    emoji + ' **NUEVO LEAD — Crea Local Miami**',
    '',
    '**Nombre:** ' + (b.nombre || '—'),
    '**Negocio:** ' + (b.negocio || '—'),
    '**Paquete:** ' + (b.paquete || 'Sin definir'),
    '**Email:** ' + (b.email || '—'),
    '**Teléfono:** ' + (b.telefono || '—'),
    '',
    b.mensaje ? ('💬 *' + b.mensaje.substring(0, 200) + '*') : '',
    '',
    '🔗 https://docs.google.com/spreadsheets/d/1s0_L2aznX1VRGs8fxIeIU5DbdmmW5-cOdtjlZZObsgM/edit'
  ].filter(Boolean).join('\n')
}}];
